    func test_arithmetic_bool() {
        for (n1, x) in layoutVariants(BA){
            for (n2, y) in layoutVariants(BB){
                XCTAssertClose(x + y, MfArray([true, true, true, false, true, true, false, true, true, true, true, true] as [Bool], shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x + y \(n1) \(n2)")
                XCTAssertClose(x * y, MfArray([true, false, false, false, false, true, false, false, false, true, false, true] as [Bool], shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x * y \(n1) \(n2)")
            }
        }
    }

    func test_arithmetic_scalar() {
        for (name, x) in layoutVariants(A){
            XCTAssertClose(x + 2, MfArray([5.0, 1.0, 2.0, 3.0, 7.0, 11.0, 0.0, 8.0, 7.0, -1.0, 7.0, 10.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x + 2 \(name)")
            XCTAssertClose(2 + x, MfArray([5.0, 1.0, 2.0, 3.0, 7.0, 11.0, 0.0, 8.0, 7.0, -1.0, 7.0, 10.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "2 + x \(name)")
            XCTAssertClose(x - 2, MfArray([1.0, -3.0, -2.0, -1.0, 3.0, 7.0, -4.0, 4.0, 3.0, -5.0, 3.0, 6.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x - 2 \(name)")
            XCTAssertClose(2 - x, MfArray([-1.0, 3.0, 2.0, 1.0, -3.0, -7.0, 4.0, -4.0, -3.0, 5.0, -3.0, -6.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "2 - x \(name)")
            XCTAssertClose(x * 2, MfArray([6.0, -2.0, 0.0, 2.0, 10.0, 18.0, -4.0, 12.0, 10.0, -6.0, 10.0, 16.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x * 2 \(name)")
            XCTAssertClose(2 * x, MfArray([6.0, -2.0, 0.0, 2.0, 10.0, 18.0, -4.0, 12.0, 10.0, -6.0, 10.0, 16.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "2 * x \(name)")
            XCTAssertClose(x / 2, MfArray([1.5, -0.5, 0.0, 0.5, 2.5, 4.5, -1.0, 3.0, 2.5, -1.5, 2.5, 4.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x / 2 \(name)")
            XCTAssertClose(Matft.sub(x, 2), MfArray([1.0, -3.0, -2.0, -1.0, 3.0, 7.0, -4.0, 4.0, 3.0, -5.0, 3.0, 6.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.sub(x, 2) \(name)")
            XCTAssertClose(x + -3, MfArray([0.0, -4.0, -3.0, -2.0, 2.0, 6.0, -5.0, 3.0, 2.0, -6.0, 2.0, 5.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x + -3 \(name)")
            XCTAssertClose(-3 + x, MfArray([0.0, -4.0, -3.0, -2.0, 2.0, 6.0, -5.0, 3.0, 2.0, -6.0, 2.0, 5.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "-3 + x \(name)")
            XCTAssertClose(x - -3, MfArray([6.0, 2.0, 3.0, 4.0, 8.0, 12.0, 1.0, 9.0, 8.0, 0.0, 8.0, 11.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "x - -3 \(name)")
            XCTAssertClose(-3 - x, MfArray([-6.0, -2.0, -3.0, -4.0, -8.0, -12.0, -1.0, -9.0, -8.0, 0.0, -8.0, -11.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "-3 - x \(name)")
