    func test_arithmetic_special_values() {
        for (n1, x) in layoutVariants(SP){
            for (n2, y) in layoutVariants(SQ){
                XCTAssertClose(x + y, MfArray([.nan, .infinity, .nan, 0.0, 0.0, 1.0, -1.0, .nan, .nan, -0.0, .nan, -.infinity] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x + y \(n1) \(n2)")
                XCTAssertClose(x - y, MfArray([.nan, .nan, -.infinity, 0.0, -0.0, 1.0, -1.0, .infinity, .nan, 0.0, .nan, .nan] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x - y \(n1) \(n2)")
                XCTAssertClose(x * y, MfArray([.nan, .infinity, -.infinity, 0.0, -0.0, -0.0, -0.0, -.infinity, .nan, 0.0, .nan, .infinity] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x * y \(n1) \(n2)")
                XCTAssertClose(x / y, MfArray([.nan, .nan, .nan, .nan, .nan, -.infinity, -.infinity, .nan, .nan, .nan, .nan, .nan] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x / y \(n1) \(n2)")
            }
        }
        for (name, x) in layoutVariants(SP){
            XCTAssertClose(1.0 / (x * 0.0), MfArray([.nan, .nan, .nan, .infinity, -.infinity, .infinity, -.infinity, .nan, .infinity, -.infinity, .nan, .nan] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "1.0 / (x * 0.0) \(name)")
            XCTAssertClose(1.0 / (-x), MfArray([.nan, -0.0, 0.0, -.infinity, .infinity, -1.0, 1.0, -0.0, -0.5, .infinity, .nan, 0.0] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "1.0 / (-x) \(name)")
            XCTAssertClose(x + Double.infinity, MfArray([.nan, .infinity, .nan, .infinity, .infinity, .infinity, .infinity, .infinity, .infinity, .infinity, .nan, .nan] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x + Double.infinity \(name)")
            XCTAssertClose(x * Double.nan, MfArray([.nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x * Double.nan \(name)")
            XCTAssertClose(-Double.infinity - x, MfArray([.nan, -.infinity, .nan, -.infinity, -.infinity, -.infinity, -.infinity, -.infinity, -.infinity, -.infinity, .nan, .nan] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "-Double.infinity - x \(name)")
        }
        for (n1, x) in layoutVariants(SPF){
            for (n2, y) in layoutVariants(SQF){
                XCTAssertClose(x + y, MfArray([.nan, .infinity, .nan, 0.0, 0.0, 1.0, -1.0, .nan, .nan, -0.0, .nan, -.infinity] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "x + y \(n1) \(n2)")
                XCTAssertClose(x - y, MfArray([.nan, .nan, -.infinity, 0.0, -0.0, 1.0, -1.0, .infinity, .nan, 0.0, .nan, .nan] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "x - y \(n1) \(n2)")
                XCTAssertClose(x * y, MfArray([.nan, .infinity, -.infinity, 0.0, -0.0, -0.0, -0.0, -.infinity, .nan, 0.0, .nan, .infinity] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "x * y \(n1) \(n2)")
                XCTAssertClose(x / y, MfArray([.nan, .nan, .nan, .nan, .nan, -.infinity, -.infinity, .nan, .nan, .nan, .nan, .nan] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "x / y \(n1) \(n2)")
            }
        }
        for (name, x) in layoutVariants(SPF){
            XCTAssertClose(Float(1.0) / (x * Float(0.0)), MfArray([.nan, .nan, .nan, .infinity, -.infinity, .infinity, -.infinity, .nan, .infinity, -.infinity, .nan, .nan] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "Float(1.0) / (x * Float(0.0)) \(name)")
            XCTAssertClose(Float(1.0) / (-x), MfArray([.nan, -0.0, 0.0, -.infinity, .infinity, -1.0, 1.0, -0.0, -0.5, .infinity, .nan, 0.0] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "Float(1.0) / (-x) \(name)")
            XCTAssertClose(x + Float.infinity, MfArray([.nan, .infinity, .nan, .infinity, .infinity, .infinity, .infinity, .infinity, .infinity, .infinity, .nan, .nan] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "x + Float.infinity \(name)")
            XCTAssertClose(x * Float.nan, MfArray([.nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan, .nan] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "x * Float.nan \(name)")
            XCTAssertClose(-Float.infinity - x, MfArray([.nan, -.infinity, .nan, -.infinity, -.infinity, -.infinity, -.infinity, -.infinity, -.infinity, -.infinity, .nan, .nan] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "-Float.infinity - x \(name)")
        }
    }

