    func test_compare_scalar_precision() {
        for (name, x) in layoutVariants(PF){
            XCTAssertClose(x > 0.1, MfArray([false, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > 0.1 \(name)")
            XCTAssertClose(x >= 0.1, MfArray([true, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x >= 0.1 \(name)")
            XCTAssertClose(x < 0.1, MfArray([false, false, false, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x < 0.1 \(name)")
            XCTAssertClose(x <= 0.1, MfArray([true, false, false, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x <= 0.1 \(name)")
            XCTAssertClose(x === 0.1, MfArray([true, false, false, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x === 0.1 \(name)")
            XCTAssertClose(x !== 0.1, MfArray([false, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x !== 0.1 \(name)")
        }
        for (name, x) in layoutVariants(P){
            XCTAssertClose(x > 0.1, MfArray([false, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > 0.1 \(name)")
            XCTAssertClose(x >= 0.1, MfArray([true, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x >= 0.1 \(name)")
            XCTAssertClose(x < 0.1, MfArray([false, false, false, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x < 0.1 \(name)")
            XCTAssertClose(x <= 0.1, MfArray([true, false, false, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x <= 0.1 \(name)")
            XCTAssertClose(x === 0.1, MfArray([true, false, false, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x === 0.1 \(name)")
            XCTAssertClose(x !== 0.1, MfArray([false, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x !== 0.1 \(name)")
            XCTAssertClose(x > Float(0.1), MfArray([false, true, true, true, true, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > Float(0.1) \(name)")
