    func test_compare_threshold() {
        for (name, x) in layoutVariants(T){
            XCTAssertClose(x > 1.0, MfArray([false, false, true, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > 1.0 \(name)")
            XCTAssertClose(x > 0.0, MfArray([true, true, true, false, false, true] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > 0.0 \(name)")
            XCTAssertClose(x > x[Matft.reverse], MfArray([true, true, true, false, false, false] as [Bool], shape: [2, 3]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > x[Matft.reverse] \(name)")
