    func test_compare_special_values() {
        for (n1, x) in layoutVariants(SP){
            for (n2, y) in layoutVariants(SQ){
                XCTAssertClose(x > y, MfArray([false, false, false, false, false, true, false, true, false, false, false, false] as [Bool], shape: [2, 6]), rtol: 0, atol: 0, checkType: true, "x > y \(n1) \(n2)")
            }
        }
        for (name, x) in layoutVariants(SP){
            XCTAssertClose(x > Double.infinity, MfArray([false, false, false, false, false, false, false, false, false, false, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > Double.infinity \(name)")
            XCTAssertClose(x > -Double.infinity, MfArray([false, true, false, true, true, true, true, true, true, true, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > -Double.infinity \(name)")
            XCTAssertClose(x > Double.nan, MfArray([false, false, false, false, false, false, false, false, false, false, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > Double.nan \(name)")
            XCTAssertClose(x > 0.0, MfArray([false, true, false, false, false, true, false, true, true, false, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > 0.0 \(name)")
            XCTAssertClose(x > x, MfArray([false, false, false, false, false, false, false, false, false, false, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "x > x \(name)")
        }
