            XCTAssertClose(Matft.logical_not(x), MfArray([false, false, true, false, false, false, false, false, false, false, false, false] as [Bool], shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.logical_not(x) \(name)")
