            XCTAssertClose(Matft.logical_not(x), MfArray([false, true, false, true, false, false, true, true, true, false, false, false] as [Bool], shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.logical_not(x) \(name)")
        }
        for (name, x) in layoutVariants(SP){
            XCTAssertClose(!x, MfArray([false, false, false, true, true, false, false, false, false, true, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "!x \(name)")
            XCTAssertClose(Matft.logical_not(x), MfArray([false, false, false, true, true, false, false, false, false, true, false, false] as [Bool], shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.logical_not(x) \(name)")
