    func test_maximum_minimum() {
        for (n1, x) in layoutVariants(A){
            for (n2, y) in layoutVariants(B){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([3.0, 4.0, 0.0, 1.0, 5.0, 9.0, 3.0, 6.0, 5.0, 7.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([2.0, -1.0, -1.0, 1.0, 5.0, -9.0, -2.0, 2.0, 1.0, -3.0, 5.0, -8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(AF){
            for (n2, y) in layoutVariants(BF){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([3.0, 4.0, 0.0, 1.0, 5.0, 9.0, 3.0, 6.0, 5.0, 7.0, 5.0, 8.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([2.0, -1.0, -1.0, 1.0, 5.0, -9.0, -2.0, 2.0, 1.0, -3.0, 5.0, -8.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(AI){
            for (n2, y) in layoutVariants(BI){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([3, 4, 0, 1, 5, 9, 3, 6, 5, 7, 5, 8] as [Int], mftype: .Int, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([2, -1, -1, 1, 5, -9, -2, 2, 1, -3, 5, -8] as [Int], mftype: .Int, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(U8A){
            for (n2, y) in layoutVariants(U8B){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([255, 1, 128, 255, 128, 254, 255, 3, 3, 200, 16, 200] as [Int], mftype: .UInt8, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([0, 1, 127, 1, 128, 2, 255, 0, 2, 100, 16, 100] as [Int], mftype: .UInt8, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(U8A){
            for (n2, y) in layoutVariants(I8F){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([0, 1, 127, 255, 128, 254, 255, 64, 100, 200, 16, 100] as [Int], mftype: .Int16, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([-1, -128, 127, 1, 127, 2, -2, 3, 2, 100, -3, -65] as [Int], mftype: .Int16, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(AI){
            for (n2, y) in layoutVariants(BF){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([3.0, 4.0, 0.0, 1.0, 5.0, 9.0, 3.0, 6.0, 5.0, 7.0, 5.0, 8.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([2.0, -1.0, -1.0, 1.0, 5.0, -9.0, -2.0, 2.0, 1.0, -3.0, 5.0, -8.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(A){
            for (n2, y) in layoutVariants(COL){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([3.0, 2.0, 2.0, 2.0, 5.0, 9.0, -2.0, 6.0, 5.0, 0.5, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([2.0, -1.0, 0.0, 1.0, -3.0, -3.0, -3.0, -3.0, 0.5, -3.0, 0.5, 0.5] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(ROW){
            for (n2, y) in layoutVariants(A){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, 4.0, 6.0, 5.0, -2.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([1.0, -2.0, 0.0, 0.25, 1.0, -2.0, -2.0, 0.25, 1.0, -3.0, 4.0, 0.25] as [Double], mftype: .Double, shape: [3, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
    }

    func test_maximum_minimum_nan() {
        for (n1, x) in layoutVariants(SP){
            for (n2, y) in layoutVariants(SQ){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([.nan, .infinity, .infinity, 0.0, 0.0, 1.0, 0.0, .infinity, .nan, -0.0, .nan, -.infinity] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([.nan, .infinity, -.infinity, 0.0, -0.0, -0.0, -1.0, -.infinity, .nan, -0.0, .nan, -.infinity] as [Double], mftype: .Double, shape: [2, 6]), rtol: 1e-10, atol: 1e-10, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
            }
        }
        for (n1, x) in layoutVariants(SPF){
            for (n2, y) in layoutVariants(SQF){
                XCTAssertClose(Matft.stats.maximum(x, y), MfArray([.nan, .infinity, .infinity, 0.0, 0.0, 1.0, 0.0, .infinity, .nan, -0.0, .nan, -.infinity] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.stats.maximum(x, y) \(n1) \(n2)")
                XCTAssertClose(Matft.stats.minimum(x, y), MfArray([.nan, .infinity, -.infinity, 0.0, -0.0, -0.0, -1.0, -.infinity, .nan, -0.0, .nan, -.infinity] as [Double], mftype: .Float, shape: [2, 6]), rtol: 1e-05, atol: 1e-05, checkType: true, "Matft.stats.minimum(x, y) \(n1) \(n2)")
