        }
    }

    func test_empty() {
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) + MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) + MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) - MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) - MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) * MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) * MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) / MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) / MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) > MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) > MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) === MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) === MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) + MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) + MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) - MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) - MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) * MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) * MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) / MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) / MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) > MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) > MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) === MfArray([] as [Double], mftype: .Double, shape: [3, 0]), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column) === MfArray([] as [Double], mftype: .Double, shape: [3, 0])")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) + COL, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) + COL")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) - COL, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) - COL")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) * COL, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) * COL")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) / COL, MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) / COL")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) > COL, MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) > COL")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [3, 0]) === COL, MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [3, 0]) === COL")
        XCTAssertClose(COL + MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "COL + MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column)")
        XCTAssertClose(COL - MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "COL - MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column)")
        XCTAssertClose(COL * MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "COL * MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column)")
        XCTAssertClose(COL / MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column), MfArray([] as [Double], mftype: .Double, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "COL / MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column)")
        XCTAssertClose(COL > MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "COL > MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column)")
        XCTAssertClose(COL === MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column), MfArray([] as [Bool], mftype: .Bool, shape: [3, 0]), rtol: 1e-10, atol: 1e-10, checkType: true, "COL === MfArray([] as [Double], mftype: .Double, shape: [3, 0], mforder: .Column)")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [0, 4]) + ROW, MfArray([] as [Double], mftype: .Double, shape: [0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [0, 4]) + ROW")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [0, 4]) - ROW, MfArray([] as [Double], mftype: .Double, shape: [0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [0, 4]) - ROW")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [0, 4]) * ROW, MfArray([] as [Double], mftype: .Double, shape: [0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [0, 4]) * ROW")
        XCTAssertClose(MfArray([] as [Double], mftype: .Double, shape: [0, 4]) / ROW, MfArray([] as [Double], mftype: .Double, shape: [0, 4]), rtol: 1e-10, atol: 1e-10, checkType: true, "MfArray([] as [Double], mftype: .Double, shape: [0, 4]) / ROW")
